function lancer(chaine, etat) {
  for (const etape of chaine) {
    const nom = etape[0];
    if (nom === "ajouter") {
      etat.valeur += etape[1];
    } else if (nom === "retirer") {
      etat.valeur = Math.max(0, etat.valeur - etape[1]);
    } else if (nom === "multiplier") {
      etat.valeur *= etape[1];
    } else if (nom === "repeter") {
      for (let i = 0; i < etape[1] && !etat.stop; i++) {
        lancer(etape[2], etat);
      }
    } else if (nom === "si_pair") {
      if (etat.valeur % 2 === 0) {
        lancer(etape[1], etat);
      }
    } else if (nom === "stop_si_plus_de") {
      if (etat.valeur > etape[1]) {
        etat.stop = true;
      }
    }
    if (etat.stop) {
      return;
    }
  }
}

